import io.github.diodeme.ji.agent.AgentEvent;
import io.github.diodeme.ji.agent.AgentRun;
import io.github.diodeme.ji.agent.AgentSession;
import io.github.diodeme.ji.agent.PermissionDecider;
import io.github.diodeme.ji.agent.RuntimeConfiguration;
import io.github.diodeme.ji.agent.ToolDefinition;
import io.github.diodeme.ji.ai.CancellationSource;

after.content:
ToolExecutionPolicy.Context context = new ToolExecutionPolicy.Context("embedded", id(), "embedded",
        "in-process", workspace, call.id(), call.name(), call.arguments(),
        snapshot.get().activeRun().orElseThrow().revision(), createdAt);
try {
    CompletableFuture<ToolBatchScheduler.BatchResult<ToolDefinition.ToolResult>> scheduled =
            toolScheduler.execute(List.of(new ToolBatchScheduler.ToolRequest<>(
                            context, handle.id() + ":" + call.id(), context.operationRevision(), permission,
                            tool.retryContract(), null,
                            () -> active.get() == handle && snapshot.get().activeRun()
                                    .filter(run -> run.runId().equals(handle.id())
                                            && run.revision() == context.operationRevision()).isPresent(),
                            () -> executeToolEffect(tool, call, handle))), handle.cancellation.token())
                    .toCompletableFuture();
    if (tool.permissionMode() == ToolDefinition.PermissionMode.ASK) {
        events.emit(new AgentEvent.PermissionChanged(id(), handle.id(), permission,
                AgentEvent.PermissionStatus.PENDING, now()));
    }
    ToolDefinition.ToolResult result = scheduled.join().items().getFirst().value();
    if (tool.permissionMode() == ToolDefinition.PermissionMode.ASK) {
        events.emit(new AgentEvent.PermissionChanged(id(), handle.id(), permission,
                AgentEvent.PermissionStatus.ALLOWED, now()));
    }
    handle.cancellation.token().throwIfCancellationRequested();
